import numpy as np

def loss(w):
    return (w - 3.0) ** 2

def grad(w):
    return 2.0 * (w - 3.0)

w, eta = 0.0, 0.25
history = []
for step in range(8):
    history.append((step, w, loss(w)))
    w = w - eta * grad(w)

for step, value, l in history:
    print(f"{step}: w={value:.4f}  L={l:.4f}")

import numpy as np

def sigmoid(z):
    return 1.0 / (1.0 + np.exp(-z))

w, b = 0.7, -1.0
for x in [0, 1, 2, 3]:
    z = w * x + b
    p = sigmoid(z)
    print(f"x={x}  z={z:+.2f}  p={p:.3f}  odds={p / (1 - p):.3f}")

print("odds ratio per unit:", np.exp(w))

import numpy as np

def gini(y):
    if len(y) == 0:
        return 0.0
    p = np.bincount(y, minlength=2) / len(y)
    return 1.0 - np.sum(p ** 2)

def best_split(x, y):
    order = np.argsort(x)
    x, y = x[order], y[order]
    best = (0.0, None)
    for i in range(1, len(x)):
        if x[i] == x[i - 1]:
            continue
        left, right = y[:i], y[i:]
        gain = gini(y) - (len(left) * gini(left) + len(right) * gini(right)) / len(y)
        if gain > best[0]:
            best = (gain, (x[i] + x[i - 1]) / 2)
    return best

x = np.array([22, 25, 28, 31, 35, 40, 45, 52, 58, 63])
y = np.array([1, 1, 1, 1, 0, 1, 0, 0, 1, 0])
print(best_split(x, y))
